// Package approval applies authenticated human task decisions after trusted review.
package approval

import (
	"context"
	"errors"
	"time"

	"github.com/Standard-Syntax/basic/go/internal/workflow"
)

var (
	ErrInvalidRequest    = errors.New("invalid task approval request")
	ErrUnauthorized      = errors.New("task approval principal is unauthorized")
	ErrElevatedRole      = errors.New("elevated approval role is required")
	ErrArtifactIntegrity = errors.New("task approval artifact integrity check failed")
	ErrApprovalConflict  = errors.New("approval ID already has different content")
	ErrApprovalState     = errors.New("invalid approval ledger state")
)

type Role string

const (
	RoleApprover         Role = "approver"
	RoleElevatedApprover Role = "elevated_approver"
)

type Principal struct {
	ID    string `json:"id"`
	Roles []Role `json:"roles"`
}

type Request struct {
	ApprovalID                  string
	DecisionTimestamp           time.Time
	Principal                   Principal
	RunID                       string
	TaskID                      string
	CandidateCommit             string
	ApprovedSpecificationDigest string
	ApprovedTaskDigest          string
	ActualChangedPaths          []string
	ExclusiveResourceLabels     []string
	Implementation              workflow.ArtifactRef
	Execution                   workflow.ArtifactRef
	Verification                workflow.ArtifactRef
	Review                      workflow.ArtifactRef
	ExpectedTaskRevision        uint64
}

type Result struct {
	ApprovalID       string
	Decision         string
	ApprovalArtifact workflow.ArtifactRef
	Elevated         bool
	RiskReasons      []string
	Replay           bool
}

type ArtifactStore interface {
	Get(context.Context, workflow.ArtifactRef) ([]byte, error)
	Put(context.Context, []byte) (workflow.ArtifactRef, error)
}

type WorkflowStore interface {
	ExecuteTask(context.Context, workflow.TaskCommand) (workflow.CommandResult, error)
}

type ApprovalStart struct {
	ApprovalID                  string
	RequestDigest               string
	RequestedAt                 time.Time
	PrincipalID                 string
	RunID                       string
	TaskID                      string
	CandidateCommit             string
	ApprovedSpecificationDigest string
	ApprovedTaskDigest          string
	ImplementationDigest        string
	ExecutionDigest             string
	VerificationDigest          string
	ReviewDigest                string
}

type DecisionCheckpoint struct {
	Result Result
	Reason string
}

type ApprovalHandle interface {
	Replay() (Result, bool)
	Decision() (DecisionCheckpoint, bool)
	SaveDecision(context.Context, DecisionCheckpoint) error
	Complete(context.Context, Result) error
	Rollback(context.Context) error
}

type ApprovalLedger interface {
	Begin(context.Context, ApprovalStart) (ApprovalHandle, error)
}

type TaskApproval struct {
	SchemaVersion               string               `json:"schema_version"`
	ApprovalID                  string               `json:"approval_id"`
	Approver                    Principal            `json:"approver"`
	Decision                    string               `json:"decision"`
	DecisionTimestamp           string               `json:"decision_timestamp"`
	Reason                      string               `json:"reason,omitempty"`
	Elevated                    bool                 `json:"elevated"`
	RiskReasons                 []string             `json:"risk_reasons"`
	RunID                       string               `json:"run_id"`
	TaskID                      string               `json:"task_id"`
	CandidateCommit             string               `json:"candidate_commit"`
	ApprovedSpecificationDigest string               `json:"approved_specification_digest"`
	ApprovedTaskDigest          string               `json:"approved_task_digest"`
	Implementation              workflow.ArtifactRef `json:"implementation"`
	Execution                   workflow.ArtifactRef `json:"execution"`
	Verification                workflow.ArtifactRef `json:"verification"`
	Review                      workflow.ArtifactRef `json:"review"`
}
package approval

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"path"
	"regexp"
	"slices"
	"sort"
	"strings"
	"time"

	"github.com/Standard-Syntax/basic/go/internal/review"
	"github.com/Standard-Syntax/basic/go/internal/workflow"
	"github.com/google/uuid"
)

var (
	commitPattern = regexp.MustCompile(`^[a-f0-9]{40}$`)
	digestPattern = regexp.MustCompile(`^[a-f0-9]{64}$`)
	labelPattern  = regexp.MustCompile(`^[a-z0-9][a-z0-9-]{0,62}$`)
)

var protectedLabels = map[string]struct{}{
	"dependency-manifest": {}, "database-schema": {}, "public-api-contract": {},
	"authentication-policy": {}, "authorization-policy": {},
	"deployment-configuration": {},
}

type Service struct {
	artifacts ArtifactStore
	workflow  WorkflowStore
	ledger    ApprovalLedger
}

func NewService(
	artifacts ArtifactStore,
	workflowStore WorkflowStore,
	configuredLedger ...ApprovalLedger,
) (*Service, error) {
	if artifacts == nil || workflowStore == nil {
		return nil, errors.New("approval artifact store and workflow store are required")
	}
	if len(configuredLedger) > 1 {
		return nil, errors.New("at most one approval ledger is allowed")
	}
	var ledger ApprovalLedger = NewMemoryApprovalLedger()
	if len(configuredLedger) == 1 {
		ledger = configuredLedger[0]
	}
	if ledger == nil {
		return nil, errors.New("approval ledger is required")
	}
	return &Service{artifacts: artifacts, workflow: workflowStore, ledger: ledger}, nil
}

func (s *Service) ApproveTask(ctx context.Context, request Request) (Result, error) {
	return s.decide(ctx, request, "approve", "")
}

func (s *Service) RequireTaskRework(
	ctx context.Context, request Request, reason string,
) (Result, error) {
	if strings.TrimSpace(reason) == "" || len(reason) > 4096 {
		return Result{}, fmt.Errorf("%w: rework reason", ErrInvalidRequest)
	}
	return s.decide(ctx, request, "rework", reason)
}

func (s *Service) decide(
	ctx context.Context, request Request, decision, reason string,
) (Result, error) {
	requestDigest, err := approvalRequestDigest(request, decision, reason)
	if err != nil {
		return Result{}, err
	}
	handle, err := s.ledger.Begin(ctx, ApprovalStart{
		ApprovalID: request.ApprovalID, RequestDigest: requestDigest,
		RequestedAt: request.DecisionTimestamp, PrincipalID: request.Principal.ID,
		RunID: request.RunID, TaskID: request.TaskID, CandidateCommit: request.CandidateCommit,
		ApprovedSpecificationDigest: request.ApprovedSpecificationDigest,
		ApprovedTaskDigest:          request.ApprovedTaskDigest,
		ImplementationDigest:        request.Implementation.Digest,
		ExecutionDigest:             request.Execution.Digest,
		VerificationDigest:          request.Verification.Digest, ReviewDigest: request.Review.Digest,
	})
	if err != nil {
		return Result{}, err
	}
	defer func() { _ = handle.Rollback(context.Background()) }()
	if replay, ok := handle.Replay(); ok {
		replay.Replay = true
		return replay, nil
	}
	if checkpoint, ok := handle.Decision(); ok {
		return s.applyCheckpoint(ctx, request, checkpoint, handle)
	}
	if err := s.validateRequest(ctx, request); err != nil {
		return Result{}, err
	}
	riskReasons := ClassifyElevatedRisk(
		request.ActualChangedPaths, request.ExclusiveResourceLabels,
	)
	elevated := len(riskReasons) > 0
	if err := authorize(request.Principal, elevated, decision); err != nil {
		return Result{}, err
	}
	approval := TaskApproval{
		SchemaVersion: "1", ApprovalID: request.ApprovalID,
		Approver: normalizedPrincipal(request.Principal), Decision: decision,
		DecisionTimestamp: request.DecisionTimestamp.UTC().Format(time.RFC3339Nano),
		Reason:            reason, Elevated: elevated, RiskReasons: riskReasons,
		RunID: request.RunID, TaskID: request.TaskID,
		CandidateCommit:             request.CandidateCommit,
		ApprovedSpecificationDigest: request.ApprovedSpecificationDigest,
		ApprovedTaskDigest:          request.ApprovedTaskDigest,
		Implementation:              request.Implementation, Execution: request.Execution,
		Verification: request.Verification, Review: request.Review,
	}
	body, err := json.Marshal(approval)
	if err != nil {
		return Result{}, fmt.Errorf("encode task approval: %w", err)
	}
	artifact, err := s.storeApproval(ctx, body)
	if err != nil {
		return Result{}, err
	}
	checkpoint := DecisionCheckpoint{Result: Result{
		ApprovalID: request.ApprovalID, Decision: decision, ApprovalArtifact: artifact,
		Elevated: elevated, RiskReasons: riskReasons,
	}, Reason: reason}
	if err := handle.SaveDecision(ctx, checkpoint); err != nil {
		return Result{}, fmt.Errorf("checkpoint human task decision: %w", err)
	}
	return s.applyCheckpoint(ctx, request, checkpoint, handle)
}

func (s *Service) applyCheckpoint(
	ctx context.Context,
	request Request,
	checkpoint DecisionCheckpoint,
	handle ApprovalHandle,
) (Result, error) {
	command := approvalCommand(
		request, checkpoint.Result.Decision, checkpoint.Reason,
		checkpoint.Result.ApprovalArtifact,
	)
	workflowResult, err := s.workflow.ExecuteTask(ctx, command)
	if err != nil {
		return Result{}, fmt.Errorf("apply human task decision: %w", err)
	}
	result := cloneResult(checkpoint.Result)
	result.Replay = workflowResult.Replay
	if err := handle.Complete(ctx, result); err != nil {
		return Result{}, fmt.Errorf("complete human task decision: %w", err)
	}
	return result, nil
}

func approvalRequestDigest(request Request, decision, reason string) (string, error) {
	body, err := json.Marshal(struct {
		Request  Request `json:"request"`
		Decision string  `json:"decision"`
		Reason   string  `json:"reason"`
	}{Request: request, Decision: decision, Reason: reason})
	if err != nil {
		return "", fmt.Errorf("encode approval request: %w", err)
	}
	sum := sha256.Sum256(body)
	return hex.EncodeToString(sum[:]), nil
}

func (s *Service) validateRequest(ctx context.Context, request Request) error {
	if err := validateRequestIdentity(request); err != nil {
		return err
	}
	if err := validateRiskInputs(request); err != nil {
		return err
	}
	if err := s.validateInputArtifacts(ctx, request); err != nil {
		return err
	}
	reportBody, err := fetchVerifiedArtifact(ctx, s.artifacts, request.Review)
	if err != nil {
		return err
	}
	report, err := decodeReviewReport(reportBody)
	if err != nil {
		return err
	}
	if !reviewReportMatches(report, request) {
		return fmt.Errorf("%w: trusted review binding", ErrInvalidRequest)
	}
	return nil
}

func validateRequestIdentity(request Request) error {
	_, approvalIDErr := uuid.Parse(request.ApprovalID)
	_, principalIDErr := uuid.Parse(request.Principal.ID)
	_, runIDErr := uuid.Parse(request.RunID)
	_, taskIDErr := uuid.Parse(request.TaskID)
	if approvalIDErr != nil || principalIDErr != nil ||
		runIDErr != nil || taskIDErr != nil || request.DecisionTimestamp.IsZero() ||
		!commitPattern.MatchString(request.CandidateCommit) ||
		!digestPattern.MatchString(request.ApprovedSpecificationDigest) ||
		!digestPattern.MatchString(request.ApprovedTaskDigest) ||
		request.ExpectedTaskRevision == 0 || len(request.ActualChangedPaths) == 0 {
		return ErrInvalidRequest
	}
	return nil
}

func validateRiskInputs(request Request) error {
	for _, changedPath := range request.ActualChangedPaths {
		if !safeRepoPath(changedPath) {
			return fmt.Errorf("%w: changed path", ErrInvalidRequest)
		}
	}
	for _, label := range request.ExclusiveResourceLabels {
		if !labelPattern.MatchString(label) {
			return fmt.Errorf("%w: resource label", ErrInvalidRequest)
		}
	}
	return nil
}

func (s *Service) validateInputArtifacts(ctx context.Context, request Request) error {
	for _, ref := range []workflow.ArtifactRef{
		request.Implementation, request.Execution, request.Verification,
	} {
		if err := verifyArtifact(ctx, s.artifacts, ref); err != nil {
			return err
		}
	}
	return nil
}

func reviewReportMatches(report review.ReviewReport, request Request) bool {
	return report.Passed && report.RunID == request.RunID && report.TaskID == request.TaskID &&
		report.CandidateCommit == request.CandidateCommit &&
		report.ApprovedSpecificationDigest == request.ApprovedSpecificationDigest &&
		report.ApprovedTaskDigest == request.ApprovedTaskDigest &&
		report.ImplementationProposalDigest == request.Implementation.Digest &&
		report.Execution.Equal(request.Execution) &&
		report.Verification.Equal(request.Verification) &&
		reviewInputMatches(report)
}

func reviewInputMatches(r review.ReviewReport) bool {
	return r.SchemaVersion == "1" && r.Request.URI != "" && r.Proposal.URI != ""
}

func authorize(principal Principal, elevated bool, decision string) error {
	hasApprover := slices.Contains(principal.Roles, RoleApprover)
	hasElevated := slices.Contains(principal.Roles, RoleElevatedApprover)
	if !hasApprover && !hasElevated {
		return ErrUnauthorized
	}
	if decision == "approve" && elevated && !hasElevated {
		return ErrElevatedRole
	}
	return nil
}

func normalizedPrincipal(value Principal) Principal {
	roles := slices.Clone(value.Roles)
	sort.Slice(roles, func(i, j int) bool { return roles[i] < roles[j] })
	return Principal{ID: value.ID, Roles: roles}
}

// ClassifyElevatedRisk deterministically returns sorted risk reasons.
func ClassifyElevatedRisk(changedPaths, resourceLabels []string) []string {
	reasons := make(map[string]struct{})
	for _, label := range resourceLabels {
		if _, protected := protectedLabels[label]; protected {
			reasons["resource:"+label] = struct{}{}
		}
	}
	for _, changedPath := range changedPaths {
		if protectedPath(changedPath) {
			reasons["path:"+changedPath] = struct{}{}
		}
	}
	result := make([]string, 0, len(reasons))
	for reason := range reasons {
		result = append(result, reason)
	}
	sort.Strings(result)
	return result
}

func protectedPath(value string) bool {
	base := path.Base(value)
	switch base {
	case "go.mod", "go.sum", "pyproject.toml", "uv.lock":
		return true
	}
	lower := strings.ToLower(value)
	return strings.HasSuffix(lower, ".proto") ||
		(strings.HasSuffix(lower, ".sql") && strings.Contains(lower, "migration")) ||
		strings.Contains(lower, "/schema/") || strings.HasPrefix(lower, "schema/") ||
		strings.HasPrefix(value, ".github/workflows/") ||
		strings.HasPrefix(lower, "deploy/") || strings.Contains(lower, "/deploy/") ||
		strings.HasPrefix(lower, "k8s/") || strings.Contains(lower, "/k8s/") ||
		strings.HasPrefix(base, "Dockerfile")
}

func safeRepoPath(value string) bool {
	return value != "" && !path.IsAbs(value) && path.Clean(value) == value &&
		!strings.HasPrefix(value, "../") && !strings.Contains(value, `\`)
}

func verifyArtifact(
	ctx context.Context, store ArtifactStore, ref workflow.ArtifactRef,
) error {
	_, err := fetchVerifiedArtifact(ctx, store, ref)
	return err
}

func fetchVerifiedArtifact(
	ctx context.Context, store ArtifactStore, ref workflow.ArtifactRef,
) ([]byte, error) {
	if err := ref.Validate(); err != nil {
		return nil, fmt.Errorf("%w: artifact reference", ErrInvalidRequest)
	}
	body, err := store.Get(ctx, ref)
	if err != nil {
		return nil, fmt.Errorf("load approval input artifact: %w", err)
	}
	sum := sha256.Sum256(body)
	if hex.EncodeToString(sum[:]) != ref.Digest {
		return nil, ErrArtifactIntegrity
	}
	return body, nil
}

func decodeReviewReport(body []byte) (review.ReviewReport, error) {
	decoder := json.NewDecoder(bytes.NewReader(body))
	decoder.DisallowUnknownFields()
	var report review.ReviewReport
	if err := decoder.Decode(&report); err != nil {
		return review.ReviewReport{}, fmt.Errorf("%w: decode review report", ErrArtifactIntegrity)
	}
	var trailing any
	if err := decoder.Decode(&trailing); !errors.Is(err, io.EOF) {
		return review.ReviewReport{}, fmt.Errorf("%w: review report trailer", ErrArtifactIntegrity)
	}
	return report, nil
}

func (s *Service) storeApproval(
	ctx context.Context, body []byte,
) (workflow.ArtifactRef, error) {
	artifact, err := s.artifacts.Put(ctx, body)
	if err != nil {
		return workflow.ArtifactRef{}, fmt.Errorf("store task approval: %w", err)
	}
	sum := sha256.Sum256(body)
	if err := artifact.Validate(); err != nil ||
		artifact.Digest != hex.EncodeToString(sum[:]) {
		return workflow.ArtifactRef{}, ErrArtifactIntegrity
	}
	return artifact, nil
}

func approvalCommand(
	request Request, decision, reason string, approval workflow.ArtifactRef,
) workflow.TaskCommand {
	id := func(label string) string {
		return uuid.NewSHA1(
			uuid.NameSpaceURL, []byte("harness:approval:"+request.ApprovalID+":"+label),
		).String()
	}
	meta := workflow.CommandEnvelope{
		CommandID: id("apply"), Actor: workflow.Actor{
			ID: request.Principal.ID, Kind: workflow.ActorHuman,
		},
		ExpectedRevision: request.ExpectedTaskRevision,
		Timestamp:        request.DecisionTimestamp.UTC(),
		CorrelationID:    id("correlation"), CausationID: id("apply:cause"),
	}
	if decision == "approve" {
		return workflow.ApproveTask{
			Meta: meta, Run: request.RunID, ID: request.TaskID,
			CandidateCommit: request.CandidateCommit, Review: request.Review,
			Approval: approval,
		}
	}
	return workflow.RequireTaskRework{
		Meta: meta, Run: request.RunID, ID: request.TaskID,
		CandidateCommit: request.CandidateCommit, Review: request.Review, Reason: reason,
	}
}
// Package publication publishes an approved candidate as one immutable branch and draft pull request.
package publication

import (
	"context"
	"errors"
	"time"

	"github.com/Standard-Syntax/basic/go/internal/workflow"
)

var (
	ErrInvalidRequest      = errors.New("invalid publication request")
	ErrArtifactIntegrity   = errors.New("publication artifact integrity check failed")
	ErrBaseDrift           = errors.New("reviewed base commit no longer matches remote base")
	ErrBranchConflict      = errors.New("publication branch already has different content")
	ErrPullRequestConflict = errors.New("pull request identity conflicts with publication")
	ErrPublicationConflict = errors.New("publication ID already has different content")
	ErrPublicationState    = errors.New("invalid publication ledger state")
	ErrResponseLimit       = errors.New("publication response limit exceeded")
)

const (
	DefaultBranchPrefix     = "harness/"
	DefaultMaxArtifactBytes = 1 << 20
	DefaultMaxBodyBytes     = 64 << 10
	DefaultTimeout          = 30 * time.Second
)

type Config struct {
	RepositoryRoot   string
	RepositoryOwner  string
	RepositoryName   string
	Remote           string
	BaseBranch       string
	BranchPrefix     string
	ActorID          string
	APIEndpoint      string
	APIVersion       string
	MaxArtifactBytes int64
	MaxBodyBytes     int64
	Timeout          time.Duration
}

type Request struct {
	PublicationID        string
	PublicationTimestamp time.Time
	RunID                string
	BaseCommit           string
	CandidateCommit      string
	Specification        workflow.ArtifactRef
	Implementation       workflow.ArtifactRef
	Execution            workflow.ArtifactRef
	Verification         workflow.ArtifactRef
	Review               workflow.ArtifactRef
	Approval             workflow.ArtifactRef
	ExpectedRunRevision  uint64
}

type Result struct {
	PublicationID       string
	Branch              string
	CandidateCommit     string
	PullRequestNumber   int64
	PullRequestURL      string
	PublicationArtifact workflow.ArtifactRef
	Replay              bool
}

type DraftPullRequest struct {
	Number int64  `json:"number"`
	URL    string `json:"html_url"`
	State  string `json:"state"`
	Draft  bool   `json:"draft"`
	Head   string `json:"head"`
	Base   string `json:"base"`
	Marker string `json:"marker,omitempty"`
}

type DraftPullRequestInput struct {
	Owner  string
	Repo   string
	Head   string
	Base   string
	Title  string
	Body   string
	Marker string
}

type ArtifactStore interface {
	Get(context.Context, workflow.ArtifactRef, int64) ([]byte, error)
	Put(context.Context, []byte) (workflow.ArtifactRef, error)
}

type WorkflowStore interface {
	ExecuteRun(context.Context, workflow.RunCommand) (workflow.CommandResult, error)
}

type GitPublisher interface {
	BaseHead(context.Context) (string, error)
	BranchHead(context.Context, string) (string, bool, error)
	Publish(context.Context, string, string) (bool, error)
}

type CredentialSource interface {
	Token(context.Context) (string, error)
}

type PullRequestClient interface {
	FindDraft(context.Context, DraftPullRequestInput) (DraftPullRequest, bool, error)
	CreateDraft(context.Context, DraftPullRequestInput) (DraftPullRequest, error)
}

type PublicationStart struct {
	PublicationID        string
	RequestDigest        string
	RequestedAt          time.Time
	Repository           string
	BaseBranch           string
	HeadBranch           string
	BaseCommit           string
	CandidateCommit      string
	SpecificationDigest  string
	ImplementationDigest string
	ExecutionDigest      string
	VerificationDigest   string
	ReviewDigest         string
	ApprovalDigest       string
	ExpectedRunRevision  uint64
}

type BranchCheckpoint struct {
	Branch          string
	CandidateCommit string
}

type PullRequestCheckpoint struct {
	Branch            string
	CandidateCommit   string
	PullRequestNumber int64
	PullRequestURL    string
}

type PublicationHandle interface {
	Replay() (Result, bool)
	Branch() (BranchCheckpoint, bool)
	SaveBranch(context.Context, BranchCheckpoint) error
	PullRequest() (PullRequestCheckpoint, bool)
	SavePullRequest(context.Context, PullRequestCheckpoint) error
	Complete(context.Context, Result) error
	Rollback(context.Context) error
}

type PublicationLedger interface {
	Begin(context.Context, PublicationStart) (PublicationHandle, error)
}

type DraftPullRequestArtifact struct {
	SchemaVersion     string               `json:"schema_version"`
	PublicationID     string               `json:"publication_id"`
	PublishedAt       string               `json:"published_at"`
	RepositoryOwner   string               `json:"repository_owner"`
	RepositoryName    string               `json:"repository_name"`
	BaseBranch        string               `json:"base_branch"`
	HeadBranch        string               `json:"head_branch"`
	BaseCommit        string               `json:"base_commit"`
	CandidateCommit   string               `json:"candidate_commit"`
	PullRequestNumber int64                `json:"pull_request_number"`
	PullRequestURL    string               `json:"pull_request_url"`
	Draft             bool                 `json:"draft"`
	Specification     workflow.ArtifactRef `json:"specification"`
	Implementation    workflow.ArtifactRef `json:"implementation"`
	Execution         workflow.ArtifactRef `json:"execution"`
	Verification      workflow.ArtifactRef `json:"verification"`
	Review            workflow.ArtifactRef `json:"review"`
	Approval          workflow.ArtifactRef `json:"approval"`
}
package publication

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/Standard-Syntax/basic/go/internal/workflow"
	"github.com/google/uuid"
)

type Service struct {
	config    Config
	artifacts ArtifactStore
	workflow  WorkflowStore
	git       GitPublisher
	pulls     PullRequestClient
	ledger    PublicationLedger
}

func NewService(
	config Config,
	artifacts ArtifactStore,
	workflowStore WorkflowStore,
	gitPublisher GitPublisher,
	pulls PullRequestClient,
	ledger PublicationLedger,
) (*Service, error) {
	normalized, err := normalizeConfig(config)
	if err != nil {
		return nil, err
	}
	if artifacts == nil || workflowStore == nil || gitPublisher == nil ||
		pulls == nil || ledger == nil {
		return nil, errors.New("publication service ports are required")
	}
	if _, err := uuid.Parse(normalized.ActorID); err != nil {
		return nil, fmt.Errorf("%w: publication actor ID", ErrInvalidRequest)
	}
	return &Service{
		config: normalized, artifacts: artifacts, workflow: workflowStore,
		git: gitPublisher, pulls: pulls, ledger: ledger,
	}, nil
}

func (s *Service) Publish(ctx context.Context, request Request) (Result, error) {
	if err := validateRequestHeader(s.config, request); err != nil {
		return Result{}, err
	}
	inputs, err := validateArtifacts(ctx, s.artifacts, s.config, request)
	if err != nil {
		return Result{}, err
	}
	rendered, err := renderPullRequest(s.config, request, inputs)
	if err != nil {
		return Result{}, err
	}
	digest, err := publicationRequestDigest(request)
	if err != nil {
		return Result{}, err
	}
	handle, err := s.ledger.Begin(ctx, PublicationStart{
		PublicationID: request.PublicationID, RequestDigest: digest,
		RequestedAt: request.PublicationTimestamp,
		Repository:  s.config.RepositoryOwner + "/" + s.config.RepositoryName,
		BaseBranch:  s.config.BaseBranch, HeadBranch: rendered.Head,
		BaseCommit: request.BaseCommit, CandidateCommit: request.CandidateCommit,
		SpecificationDigest:  request.Specification.Digest,
		ImplementationDigest: request.Implementation.Digest,
		ExecutionDigest:      request.Execution.Digest,
		VerificationDigest:   request.Verification.Digest,
		ReviewDigest:         request.Review.Digest, ApprovalDigest: request.Approval.Digest,
		ExpectedRunRevision: request.ExpectedRunRevision,
	})
	if err != nil {
		return Result{}, fmt.Errorf("reserve publication: %w", err)
	}
	if replay, ok := handle.Replay(); ok {
		replay.Replay = true
		return replay, nil
	}
	return s.publishReserved(ctx, request, rendered, handle)
}

func (s *Service) publishReserved(
	ctx context.Context,
	request Request,
	rendered DraftPullRequestInput,
	handle PublicationHandle,
) (Result, error) {
	branch, ready := handle.Branch()
	if !ready {
		head, err := s.git.BaseHead(ctx)
		if err != nil {
			_ = handle.Rollback(ctx)
			return Result{}, fmt.Errorf("inspect publication base: %w", err)
		}
		if head != request.BaseCommit {
			_ = handle.Rollback(ctx)
			return Result{}, ErrBaseDrift
		}
		if _, err := s.git.Publish(ctx, rendered.Head, request.CandidateCommit); err != nil {
			_ = handle.Rollback(ctx)
			return Result{}, err
		}
		branch = BranchCheckpoint{Branch: rendered.Head, CandidateCommit: request.CandidateCommit}
		if err := handle.SaveBranch(ctx, branch); err != nil {
			return Result{}, fmt.Errorf("checkpoint publication branch: %w", err)
		}
	}
	if branch.Branch != rendered.Head || branch.CandidateCommit != request.CandidateCommit {
		return Result{}, ErrPublicationConflict
	}
	checkpoint, ready := handle.PullRequest()
	if !ready {
		head, err := s.git.BaseHead(ctx)
		if err != nil {
			return Result{}, fmt.Errorf("recheck publication base: %w", err)
		}
		if head != request.BaseCommit {
			return Result{}, ErrBaseDrift
		}
		pr, exists, err := s.pulls.FindDraft(ctx, rendered)
		if err != nil {
			return Result{}, fmt.Errorf("find draft pull request: %w", err)
		}
		if !exists {
			pr, err = s.pulls.CreateDraft(ctx, rendered)
			if err != nil {
				recovered, found, findErr := s.pulls.FindDraft(ctx, rendered)
				if findErr != nil || !found {
					return Result{}, fmt.Errorf("create draft pull request: %w", err)
				}
				pr = recovered
			}
		}
		checkpoint = PullRequestCheckpoint{
			Branch: rendered.Head, CandidateCommit: request.CandidateCommit,
			PullRequestNumber: pr.Number, PullRequestURL: pr.URL,
		}
		if err := handle.SavePullRequest(ctx, checkpoint); err != nil {
			return Result{}, fmt.Errorf("checkpoint draft pull request: %w", err)
		}
	}
	return s.complete(ctx, request, checkpoint, handle)
}

func (s *Service) complete(
	ctx context.Context,
	request Request,
	checkpoint PullRequestCheckpoint,
	handle PublicationHandle,
) (Result, error) {
	artifact := DraftPullRequestArtifact{
		SchemaVersion: "1", PublicationID: request.PublicationID,
		PublishedAt:     request.PublicationTimestamp.UTC().Format(time.RFC3339Nano),
		RepositoryOwner: s.config.RepositoryOwner, RepositoryName: s.config.RepositoryName,
		BaseBranch: s.config.BaseBranch, HeadBranch: checkpoint.Branch,
		BaseCommit: request.BaseCommit, CandidateCommit: checkpoint.CandidateCommit,
		PullRequestNumber: checkpoint.PullRequestNumber, PullRequestURL: checkpoint.PullRequestURL,
		Draft: true, Specification: request.Specification, Implementation: request.Implementation,
		Execution: request.Execution, Verification: request.Verification,
		Review: request.Review, Approval: request.Approval,
	}
	body, err := json.Marshal(artifact)
	if err != nil {
		return Result{}, fmt.Errorf("encode publication artifact: %w", err)
	}
	ref, err := s.artifacts.Put(ctx, body)
	if err != nil {
		return Result{}, fmt.Errorf("store publication artifact: %w", err)
	}
	sum := sha256.Sum256(body)
	if err := ref.Validate(); err != nil || ref.Digest != hex.EncodeToString(sum[:]) {
		return Result{}, ErrArtifactIntegrity
	}
	recorded, err := s.workflow.ExecuteRun(ctx, workflow.RecordDraftPullRequest{
		Meta: workflow.CommandEnvelope{
			CommandID:        request.PublicationID,
			Actor:            workflow.Actor{ID: s.config.ActorID, Kind: workflow.ActorPublicationService},
			ExpectedRevision: request.ExpectedRunRevision,
			Timestamp:        request.PublicationTimestamp.UTC(),
			CorrelationID:    request.RunID, CausationID: request.PublicationID,
		},
		ID: request.RunID, CandidateCommit: request.CandidateCommit,
		Approval: request.Approval, Publication: ref,
	})
	if err != nil {
		return Result{}, fmt.Errorf("record draft pull request: %w", err)
	}
	result := Result{
		PublicationID: request.PublicationID, Branch: checkpoint.Branch,
		CandidateCommit:   request.CandidateCommit,
		PullRequestNumber: checkpoint.PullRequestNumber, PullRequestURL: checkpoint.PullRequestURL,
		PublicationArtifact: ref, Replay: recorded.Replay,
	}
	if err := handle.Complete(ctx, result); err != nil {
		return Result{}, fmt.Errorf("complete publication: %w", err)
	}
	return result, nil
}

func publicationRequestDigest(request Request) (string, error) {
	encoded, err := json.Marshal(request)
	if err != nil {
		return "", fmt.Errorf("encode publication request: %w", err)
	}
	sum := sha256.Sum256(encoded)
	return hex.EncodeToString(sum[:]), nil
}

package publication

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"regexp"
	"strings"
)

var (
	commitPattern = regexp.MustCompile(`^[a-f0-9]{40}$`)
	branchPattern = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._/-]{0,199}$`)
)

type GitCommandPublisher struct {
	root       string
	remote     string
	baseBranch string
}

func NewGitCommandPublisher(root, remote, baseBranch string) (*GitCommandPublisher, error) {
	if strings.TrimSpace(root) == "" || !branchPattern.MatchString(remote) ||
		!branchPattern.MatchString(baseBranch) {
		return nil, fmt.Errorf("%w: git configuration", ErrInvalidRequest)
	}
	return &GitCommandPublisher{root: root, remote: remote, baseBranch: baseBranch}, nil
}

func (p *GitCommandPublisher) BaseHead(ctx context.Context) (string, error) {
	head, exists, err := p.remoteHead(ctx, p.baseBranch)
	if err != nil {
		return "", err
	}
	if !exists {
		return "", fmt.Errorf("%w: remote base branch is missing", ErrBaseDrift)
	}
	return head, nil
}

func (p *GitCommandPublisher) BranchHead(
	ctx context.Context, branch string,
) (string, bool, error) {
	if !branchPattern.MatchString(branch) {
		return "", false, fmt.Errorf("%w: branch name", ErrInvalidRequest)
	}
	return p.remoteHead(ctx, branch)
}

func (p *GitCommandPublisher) Publish(
	ctx context.Context, branch, candidate string,
) (bool, error) {
	if !branchPattern.MatchString(branch) || !commitPattern.MatchString(candidate) {
		return false, fmt.Errorf("%w: branch publication binding", ErrInvalidRequest)
	}
	if err := p.run(ctx, nil, "cat-file", "-e", candidate+"^{commit}"); err != nil {
		if ctxErr := ctx.Err(); ctxErr != nil {
			return false, ctxErr
		}
		return false, fmt.Errorf("%w: candidate commit is unavailable: %v", ErrInvalidRequest, err)
	}
	head, exists, err := p.BranchHead(ctx, branch)
	if err != nil {
		return false, err
	}
	if exists {
		if head == candidate {
			return true, nil
		}
		return false, ErrBranchConflict
	}
	ref := "refs/heads/" + branch
	pushErr := p.run(ctx, nil, "push", "--porcelain", "--no-verify",
		"--force-with-lease="+ref+":", p.remote, candidate+":"+ref)
	if pushErr == nil {
		return false, nil
	}
	head, exists, inspectErr := p.BranchHead(ctx, branch)
	if inspectErr == nil && exists && head == candidate {
		return true, nil
	}
	if inspectErr == nil && exists {
		return false, ErrBranchConflict
	}
	return false, fmt.Errorf("publish candidate branch: %w", pushErr)
}

func (p *GitCommandPublisher) remoteHead(
	ctx context.Context, branch string,
) (string, bool, error) {
	var output bytes.Buffer
	err := p.run(ctx, &output, "ls-remote", "--heads", p.remote, "refs/heads/"+branch)
	if err != nil {
		return "", false, fmt.Errorf("inspect remote branch: %w", err)
	}
	fields := strings.Fields(output.String())
	if len(fields) == 0 {
		return "", false, nil
	}
	if len(fields) != 2 || !commitPattern.MatchString(fields[0]) {
		return "", false, errors.New("invalid git ls-remote response")
	}
	return fields[0], true, nil
}

func (p *GitCommandPublisher) run(
	ctx context.Context, stdout *bytes.Buffer, args ...string,
) error {
	command := exec.CommandContext(ctx, "git", args...)
