func (c ProviderConfig) Normalize() (ProviderConfig, error) {
	if c.Mode == "" {
		c.Mode = MiniMaxMode
	}
	if c.Mode == FakeProviderMode {
		if c.BaseURL != "" || c.Model != "" || c.APIKeyEnv != "" {
			return ProviderConfig{}, errors.New("fake provider does not accept remote configuration")
